package org.apache.commons.math.analysis.solvers;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.analysis.UnivariateFunction;
import org.apache.commons.math.exception.MathInternalError;
import org.apache.commons.math.exception.NoBracketingException;
import org.apache.commons.math.exception.NumberIsTooSmallException;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.Precision;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertThrows;

/**
 * Unit tests for BracketingNthOrderBrentSolver.doSolve().
 * Since doSolve() is protected, we test it via the public solve() method 
 * which invokes doSolve() under various configurations.
 */
public class BracketingNthOrderBrentSolver_doSolve_TriageGen0Test {

    private static final double EPSILON = 1e-7;

    @Test
    public void testSolve_InitialGuessIsPerfectRoot() {
        BracketingNthOrderBrentSolver solver = new BracketingNthOrderBrentSolver();
        // f(x) = x - 2. Start value is 2, which is the root.
        UnivariateFunction f = x -> x - 2.0;
        double root = solver.solve(100, f, 0.0, 5.0, 2.0, AllowedSolution.ANY_SIDE);
        assertEquals(2.0, root, EPSILON);
    }

    @Test
    public void testSolve_MinEndpointIsPerfectRoot() {
        BracketingNthOrderBrentSolver solver = new BracketingNthOrderBrentSolver();
        // f(x) = x. Min is 0, which is the root.
        UnivariateFunction f = x -> x;
        double root = solver.solve(100, f, 0.0, 5.0, 2.5, AllowedSolution.ANY_SIDE);
        assertEquals(0.0, root, EPSILON);
    }

    @Test
    public void testSolve_MaxEndpointIsPerfectRoot() {
        BracketingNthOrderBrentSolver solver = new BracketingNthOrderBrentSolver();
        // f(x) = x - 5. Max is 5, which is the root.
        UnivariateFunction f = x -> x - 5.0;
        double root = solver.solve(100, f, 0.0, 5.0, 2.5, AllowedSolution.ANY_SIDE);
        assertEquals(5.0, root, EPSILON);
    }

    @Test
    public void testSolve_NoBracketingException() {
        BracketingNthOrderBrentSolver solver = new BracketingNthOrderBrentSolver();
        // f(x) = x^2 + 1. No root in [0, 5].
        UnivariateFunction f = x -> x * x + 1.0;
        assertThrows(NoBracketingException.class, () -> {
            solver.solve(100, f, 0.0, 5.0, 2.5, AllowedSolution.ANY_SIDE);
        });
    }

    @Test
    public void testSolve_BracketedInFirstInterval() {
        // y[0] * y[1] < 0
        BracketingNthOrderBrentSolver solver = new BracketingNthOrderBrentSolver();
        // f(x) = x - 1. min=0 (f=-1), start=2 (f=1). Root is 1.
        UnivariateFunction f = x -> x - 1.0;
        double root = solver.solve(100, f, 0.0, 5.0, 2.0, AllowedSolution.ANY_SIDE);
        assertEquals(1.0, root, EPSILON);
    }

    @Test
    public void testSolve_BracketedInSecondInterval() {
        // y[1] * y[2] < 0
        BracketingNthOrderBrentSolver solver = new BracketingNthOrderBrentSolver();
        // f(x) = x - 4. min=0 (f=-4), start=1 (f=-3), max=5 (f=1). Root is 4.
        UnivariateFunction f = x -> x - 4.0;
        double root = solver.solve(100, f, 0.0, 5.0, 1.0, AllowedSolution.ANY_SIDE);
        assertEquals(4.0, root, EPSILON);
    }

    @Test
    public void testSolve_AllowedSolution_LeftSide() {
        BracketingNthOrderBrentSolver solver = new BracketingNthOrderBrentSolver();
        // Linear function, root at 2.
        UnivariateFunction f = x -> x - 2.0;
        // We force a convergence scenario where we might pick a side.
        // Using a very high accuracy to trigger the switch.
        double root = solver.solve(100, f, 0.0, 5.0, 2.0, AllowedSolution.LEFT_SIDE);
        // Since it's a perfect root, it returns x[1] or the exact match.
        assertEquals(2.0, root, EPSILON);
    }

    @Test
    public void testSolve_AllowedSolution_RightSide() {
        BracketingNthOrderBrentSolver solver = new BracketingNthOrderBrentSolver();
        UnivariateFunction f = x -> x - 2.0;
        double root = solver.solve(100, f, 0.0, 5.0, 2.0, AllowedSolution.RIGHT_SIDE);
        assertEquals(2.0, root, EPSILON);
    }

    @Test
    public void testSolve_AllowedSolution_BelowSide() {
        BracketingNthOrderBrentSolver solver = new BracketingNthOrderBrentSolver();
        UnivariateFunction f = x -> x - 2.0;
        double root = solver.solve(100, f, 0.0, 5.0, 2.0, AllowedSolution.BELOW_SIDE);
        assertEquals(2.0, root, EPSILON);
    }

    @Test
    public void testSolve_AllowedSolution_AboveSide() {
        BracketingNthOrderBrentSolver solver = new BracketingNthOrderBrentSolver();
        UnivariateFunction f = x -> x - 2.0;
        double root = solver.solve(100, f, 0.0, 5.0, 2.0, AllowedSolution.ABOVE_SIDE);
        assertEquals(2.0, root, EPSILON);
    }

    @Test
    public void testSolve_BisectionFallback() {
        // To trigger bisection, the interpolation must fail (nextX not in interval).
        // We can use a highly non-linear function or a function that causes NaN/out of bounds.
        BracketingNthOrderBrentSolver solver = new BracketingNthOrderBrentSolver(1e-10, 1e-10, 10);
        // Function that is difficult for polynomial interpolation
        UnivariateFunction f = x -> Math.sin(1.0 / x);
        // Note: Finding a root for sin(1/x) is unstable, but we aim to trigger the path.
        // A simpler way: a function where interpolation produces a value outside [xA, xB]
        // We use a solver with low maximalOrder to force logic into the do-while loop.
        BracketingNthOrderBrentSolver solverSmallOrder = new BracketingNthOrderBrentSolver(1e-10, 2);
        UnivariateFunction fComplex = x -> Math.pow(x - 2, 3) + (x - 2); 
        double root = solverSmallOrder.solve(100, fComplex, 0.0, 5.0, 2.0, AllowedSolution.ANY_SIDE);
        assertEquals(2.0, root, 1e-5);
    }

    @Test
    public void testSolve_AgingAndRedirection() {
        // Testing the aging logic (MAXIMAL_AGING) by providing a function 
        // that stays on one side for many iterations.
        BracketingNthOrderBrentSolver solver = new BracketingNthOrderBrentSolver(1e-10, 10);
        // f(x) = x - 2.5
        UnivariateFunction f = x -> x - 2.5;
        double root = solver.solve(200, f, 0.0, 5.0, 1.0, AllowedSolution.ANY_SIDE);
        assertEquals(2.5, root, 1e-7);
    }

    @Test(expected = NumberIsTooSmallException.class)
    public void testConstructor_InvalidAccuracy() throws NumberIsTooSmallException {
        new BracketingNthOrderBrentSolver(1e-20, 1e-20, 10);
    }
}
